import React from 'react';

const Header: React.FC = () => {
    return (
        <header>
            <h1>Chatbot Intercom System</h1>
            <nav>
                <ul>
                    <li>Home</li>
                    <li>Chat</li>
                    <li>Intercom</li>
                    <li>Media</li>
                </ul>
            </nav>
        </header>
    );
};

export default Header;
